package com.trombokendu.chronos.ingest;import com.trombokendu.chronos.concurrency.*;import java.nio.file.*;import java.util.concurrent.*;public final class FolderWatcher implements AutoCloseable{private final WatchService watcher;private final Thread thread;private volatile boolean running=true;public FolderWatcher(Path dir,StatementParser parser,LedgerWriter writer)throws Exception{Files.createDirectories(dir);watcher=FileSystems.getDefault().newWatchService();dir.register(watcher,StandardWatchEventKinds.ENTRY_CREATE);thread=new Thread(()->{while(running)try{WatchKey k=watcher.take();for(WatchEvent<?> e:k.pollEvents()){Path f=dir.resolve((Path)e.context());if(f.toString().endsWith(".csv"))for(var event:parser.parse(f))writer.submit(event);}k.reset();}catch(InterruptedException x){Thread.currentThread().interrupt();break;}},"folder-watcher");thread.setDaemon(true);thread.start();}public void close(){running=false;try{watcher.close();thread.interrupt();thread.join(1000);}catch(Exception ignored){}}}
